function tableData = standardizeOutputTable(tableData, context)
%STANDARDIZEOUTPUTTABLE Apply readable output names and explicit units.
%
% Inputs
%   tableData Result table generated by an analysis module.
%   context   One of "global", "plaques", "layers", or "spheres".
%
% Output
%   tableData Table with standardized metadata names and unit suffixes.

    if isempty(tableData)
        return;
    end

    context = string(context);
    exactMap = getExactNameMap();
    oldNames = string(tableData.Properties.VariableNames);
    newNames = oldNames;

    for i = 1:numel(oldNames)
        name = oldNames(i);
        validField = matlab.lang.makeValidName(name);
        if isfield(exactMap, validField)
            if name == "MicrogliaDensityTotal" && context == "layers"
                newNames(i) = "MicrogliaDensityTotal_cells_mm3";
            else
                newNames(i) = string(exactMap.(validField));
            end
        else
            newNames(i) = standardizeDynamicName(name, context);
        end
    end

    newNames = string(matlab.lang.makeUniqueStrings(cellstr(newNames)));
    tableData.Properties.VariableNames = cellstr(newNames);
end

