function newName = standardizeDynamicName(name, context)
%STANDARDIZEDYNAMICNAME Add units to repeated layer, sphere, and Voronoi fields.
    newName = name;

    replacements = {
        'MicrogliaDensitymm3$', 'MicrogliaDensity_cells_mm3';
        'MicrogliaDensity$', 'MicrogliaDensity_cells_mm3';
        'PlaquesDensitymm3$', 'PlaqueDensity_plaques_mm3';
        'PlaquesDensity$', 'PlaqueDensity_plaques_mm3';
        'MeanPlaquesVolume$', 'MeanPlaqueVolume_um3';
        'StdPlaquesVolume$', 'StdPlaqueVolume_um3';
        'Volume$', 'Volume_um3';
        'SurfaceArea', 'SurfaceArea_um2';
        'MeanSurface', 'MeanSurfaceArea_um2';
        'StdSurface', 'StdSurfaceArea_um2';
        'MeanVolume', 'MeanVolume_um3';
        'StdVolume', 'StdVolume_um3';
        'DistNeighs', 'NeighborDistance_um';
        'DistanceNeighbours', 'NeighborDistance_um';
        'MicrogliaDistToNearest_Mean', 'MeanNearestMicrogliaDistance_um';
        'MicrogliaDistToNearest_Std', 'StdNearestMicrogliaDistance_um';
        'MicrogliaDist_Mean', 'MeanPairwiseMicrogliaDistance_um';
        'MicrogliaDist_Std', 'StdPairwiseMicrogliaDistance_um'};

    for i = 1:size(replacements, 1)
        newName = string(regexprep(char(newName), replacements{i, 1}, replacements{i, 2}));
    end

    if context == "spheres"
        newName = replace(newName, "MicrogliaDensity", "MicrogliaDensity_cells_mm3");
        newName = replace(newName, "Vol_Plaque", "PlaqueVolume_um3");
        newName = replace(newName, "VolPlaque", "PlaqueVolume_um3");
    end
end
